      const g = await page(url);
      if (g.robot) { blocked = true; rec.status = 'blocked'; console.log('BrickLink asked for a robot check: stopping this run.'); break; }
      if (g.error) { rec.status = 'error: ' + g.error.slice(0, 80); continue; }
      const c = { status: g.cells ? 'ok' : 'not_found', bl_item_id: id, url, checked_at: new Date().toISOString() };
      if (g.cells) COLS.forEach((k, i) => c[k] = cell(g.cells[i]));
      fs.writeFileSync(cf, JSON.stringify(c)); if (c.status == 'ok') { Object.assign(rec, c); break; }
    }
    out.push(rec);
  }
  if (b) await b.close();
  const o = file.replace(/\.csv$/, '') + '-prices.csv', f = v => v ? v.qty_avg_usd.toFixed(3) : '';
  const lines = [['part_num', 'color_name', 'bl_item_id', 'bl_color_id', 'quantity', 'sold6m_new_usd', 'sold6m_used_usd', 'stock_new_usd', 'stock_used_usd', 'line_new_usd', 'status', 'url', 'checked_at', 'source'].join(',')];
  let tot = 0;
  for (const r of out) { const ln = r.sold_new ? r.sold_new.qty_avg_usd * r.quantity : 0; tot += ln;
    lines.push([r.part_num, `"${r.color_name}"`, r.bl_item_id || '', r.bl_color_id, r.quantity, f(r.sold_new), f(r.sold_used), f(r.stock_new), f(r.stock_used), ln ? ln.toFixed(2) : '', r.status, r.url || r.tried[0] || '', r.checked_at || '', 'bricklink price guide page' + (r.cached ? ' (cached)' : '')].join(',')); }
  fs.writeFileSync(o, lines.join('\n') + '\n');
  const bad = out.filter(r => r.status != 'ok');
  console.log(`priced ${out.length - bad.length}/${out.length}; 6-month sold new total for priced rows: US $${tot.toFixed(2)}; wrote ${o}`);
  if (bad.length) { console.log('Not priced:'); bad.forEach(r => console.log(`  ${r.part_num} ${r.color_name} (${r.status}) tried ${r.tried.join(' ')}`)); }
})();
